int minimumTourLength(int N, int[] X) {
    int totalLength = 0;
    for (int i = 1; i < N; i++) {
        totalLength += Math.abs(X[i] - X[i - 1]);
    }

    int minTourLength = Integer.MAX_VALUE;
    for (int i = 1; i < N - 1; i++) {
        int closedBridgeLength = totalLength - Math.abs(X[i] - X[i - 1]) - Math.abs(X[i + 1] - X[i]) + Math.abs(X[i + 1] - X[i - 1]);
        minTourLength = Math.min(minTourLength, closedBridgeLength);
    }

    return minTourLength;
}
